using System.Text.Json;

namespace TerminalDeck.Core.Receiver;

public sealed record ReceiverProof(string Scheme = "token", string Header = "Authorization", string Prefix = "Bearer ", string Algorithm = "sha256", string Encoding = "hex", string SignedPayload = "{body}", string? TimestampHeader = null, int ToleranceSeconds = 300, string? BasicUser = null, string[]? IpAllow = null);
public sealed record ReceiverPayloadMapping(string? Split = null, string Kind = "{{header.x-receiver-event|event|type|\"event\"}}", string Severity = "{{severity|level|\"info\"}}", string Title = "{{title|subject|summary|name}}", string Text = "{{message|text|body|description}}", string Time = "{{timestamp|time|created_at}}", string UpstreamId = "{{header.x-receiver-delivery|header.idempotency-key|id}}", Dictionary<string, string>? Fields = null, Dictionary<string, string>? Overrides = null, ReceiverCondition[]? Ignore = null);
public sealed record ReceiverReplyChannel(string Via = "http", string Method = "POST", string Url = "", Dictionary<string, string>? Headers = null, string Body = "{\"text\":\"{{reply}}\"}", string Repository = "{{fields.repo}}", string Number = "{{fields.number}}");
public sealed record ReceiverSourceConfiguration(string SourceId, string Preset, ReceiverProof Proof, ReceiverPayloadMapping Mapping, ReceiverReplyChannel? Reply = null, string? SecretReference = null, string? ReplySecretReference = null);
public sealed record ReceiverSourcePreset(string Id, string Name, ReceiverProof Proof, ReceiverPayloadMapping Mapping, ReceiverReplyChannel? Reply = null, bool BuiltIn = true);
public sealed record ReceiverReplyOutcome(string Id, string ItemId, DateTimeOffset At, string TextDigest, string State, string? Reference = null, string? Problem = null);
public sealed record ReceiverSourceSettingsState(ReceiverSourceConfiguration[] Sources, ReceiverSourcePreset[] Presets, ReceiverReplyOutcome[] Replies, string? RelayKeyReference = null, string[]? RelayDeliveries = null, string[]? PendingCredentialDeletes = null);
public sealed record ReceiverMappedPayload(string Kind, string Severity, string Title, string Text, string Time, string UpstreamId, Dictionary<string, string> Fields, JsonElement Payload, bool Ignored);
public sealed record ReceiverWebhook(string SourceId, IReadOnlyDictionary<string, string> Headers, byte[] Body, string? ClientIp = null, string? PathToken = null, string? DeliveryId = null);

